<?php
$id=(string)($_GET['id']??'');$idea=current(array_filter($ideas,fn($i)=>(string)($i['id']??'')===$id))?:null;
if(!$idea){echo '<div class="page-container inner-page"><p>الفكرة غير موجودة.</p></div>';return;}
if(is_admin()&&(string)($idea['status']??'')==='draft'){flash('المسودات خاصة بصاحب الفكرة');redirect(url('ideas'));}
$user=current_user();$ownsById=(string)($idea['employee_id']??'')!==''&&(string)($idea['employee_id']??'')===(string)($user['id']??'');$ownsByName=(string)($idea['employee']??'')===(string)($user['name']??'');
if(!is_admin()&&!$ownsById&&!$ownsByName){flash('لا يمكنك عرض فكرة تخص مستخدمًا آخر');redirect(url('ideas'));}
$ev=is_array($idea['evaluation']??null)?$idea['evaluation']:null;$status=(string)($idea['status']??'draft');$isDraft=$status==='draft';
?>
<div class="page-container inner-page"><a class="back-button" href="<?=url('ideas')?>"><?=icon('arrow-right',19)?>العودة للأفكار</a>
<div class="details-header"><div><span><?=e((string)($idea['number']??''))?></span><h1><?=e((string)($idea['title']??'مسودة بدون عنوان'))?></h1><p><?php if(is_admin()):?>مقدم الفكرة: <?=e((string)($idea['employee']??'غير محدد'))?> — <?php endif?><?=e((string)(($idea['department']??'')?:'أخرى'))?> — <?=e((string)(($idea['category']??'')?:'أخرى'))?></p></div><div class="details-header-actions"><span class="status status-<?=e($status)?>"><?=status_text($status)?></span><?php if($isDraft&&!is_admin()):?><a class="primary-button" href="<?=url('new',['id'=>(string)$idea['id']])?>"><?=icon('file',18)?>إكمال المسودة</a><?php endif?></div></div>
<div class="details-grid"><section class="data-card details-copy"><h2>تفاصيل الفكرة</h2><dl><div><dt>الوصف</dt><dd><?=e(trim((string)($idea['description']??''))!==''?(string)$idea['description']:'لم تتم إضافة وصف للفكرة بعد.')?></dd></div><div><dt>الإدارة</dt><dd><?=e((string)(($idea['department']??'')?:'أخرى'))?></dd></div><div><dt>التصنيف</dt><dd><?=e((string)(($idea['category']??'')?:'أخرى'))?></dd></div></dl><?php if($isDraft):?><div class="draft-notice">هذه الفكرة محفوظة كمسودة ولم تُرسل بعد.</div><?php endif?></section>
<section class="data-card score-panel"><h2>النتيجة العامة للذكاء الاصطناعي</h2><?php if(is_numeric($idea['score']??null)):?><div class="score-ring" style="--score:<?=((float)$idea['score']/5*100)?>%"><div><strong><?=number_format((float)$idea['score'],1)?></strong><span>/5</span></div></div><p>التقييم النهائي المستخدم في ترتيب أفضل خمس أفكار.</p><?php elseif($isDraft):?><div class="pending-score"><?=icon('save',42)?><h3>الفكرة محفوظة كمسودة</h3></div><?php else:?><div class="pending-score"><?=icon('lightbulb',42)?><h3><?=$status==='submitted'?'الفكرة بانتظار التحليل':'الفكرة قيد التحليل'?></h3></div><?php endif?></section></div>
<?php if($ev):$criteria=[['الابتكار',$ev['innovation']??0],['سهولة التنفيذ',$ev['feasibility']??0],['الاستدامة',$ev['sustainability']??0],['التكلفة',$ev['cost']??0],['القيمة التجارية',$ev['business_value']??0]];?>
<div class="details-grid lower"><section class="data-card"><h2>نتائج معايير التقييم من 5</h2><div class="criteria-list"><?php foreach($criteria as [$n,$v]):?><div><span><?=$n?></span><div><i style="width:<?=((float)$v/5*100)?>%"></i></div><b><?=number_format((float)$v,1)?></b></div><?php endforeach?></div></section><section class="data-card feedback-list"><h2><?=icon('check',20)?>نقاط القوة</h2><ul><?php foreach(($ev['strengths']??[]) as $x):?><li><?=e((string)$x)?></li><?php endforeach?></ul><h2><?=icon('wrench',20)?>فرص التحسين المقترحة من AI</h2><ul><?php foreach(($ev['improvements']??[]) as $x):?><li><?=e((string)$x)?></li><?php endforeach?></ul></section></div>
<section class="data-card improved-card"><h2>اقتراحات وتحسينات بواسطة الذكاء</h2><?php $aiSummary=trim((string)($ev['feedback']??'')); if($aiSummary===''){ $firstImprovement=(string)(($ev['improvements'][0]??'')); $aiSummary=$firstImprovement!==''?'يوصى بالتركيز على '.$firstImprovement:''; } if($aiSummary!==''):?><p class="ai-feedback"><?=e($aiSummary)?></p><?php endif?><h3><?=e((string)($ev['improvedTitle']??''))?></h3><p><?=e((string)($ev['improvedDescription']??''))?></p></section><?php endif?>
<?php if(is_admin()&&!$isDraft):?><section class="data-card admin-decision-card"><div><h2>قرار مدير النظام</h2></div><form method="post" class="admin-decision-actions admin-decision-text-actions"><input type="hidden" name="form_action" value="admin_idea_decision"><input type="hidden" name="idea_id" value="<?=e((string)$idea['id'])?>"><input type="hidden" name="return_to" value="details"><button class="decision-reject" type="submit" name="decision" value="rejected" onclick="return confirm('هل أنت متأكد من رفض هذه الفكرة؟')"><?=icon('close',18)?>رفض الفكرة</button><?php if($status==='evaluated'):?><button class="decision-approve" type="submit" name="decision" value="approved"><?=icon('check',18)?>ترشيح للتنفيذ</button><?php endif?></form></section><?php endif?></div>
